import itertools
from pysat.solvers import Solver
from pysat.formula import CNF

# Let's try a direct construction approach first
# We'll use a structured graph construction

# Approach: Use a circulant graph or similar regular structure
# A 5-regular graph on 19 vertices where clique number <= 5

# Let's try the Petersen-like construction or circulant graph
# Circulant graph C(19, {1,2,3,4,5}) - connect each vertex to 5 neighbors on each side
# But that would be 10-regular

# Let's try C(19, {1,2}) - connect to 2 neighbors each side = 4-regular (not enough)
# C(19, {1,2,3}) - connect to 3 neighbors each side = 6-regular

def make_circulant(n, offsets):
    edges = set()
    for v in range(n):
        for d in offsets:
            u = (v + d) % n
            if u != v:
                e = (min(v,u), max(v,u))
                edges.add(e)
    return sorted(edges)

def check_clique_number(n, edges):
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = True
        adj[v][u] = True

    max_clique = 1
    # Check all subsets up to size 6
    for size in range(2, 7):
        found = False
        for subset in itertools.combinations(range(n), size):
            is_clique = True
            for i in range(len(subset)):
                for j in range(i+1, len(subset)):
                    if not adj[subset[i]][subset[j]]:
                        is_clique = False
                        break
                if not is_clique:
                    break
            if is_clique:
                max_clique = size
                found = True
        if not found:
            break
    return max_clique

def check_chromatic_number(n, edges):
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = True
        adj[v][u] = True

    # Try greedy coloring with different orderings
    for k in range(1, 7):
        # Try to k-color using SAT
        cnf = CNF()
        # Variables: x[v][c] = vertex v has color c, encoded as v*k + c + 1
        def var(v, c):
            return v * k + c + 1

        # Each vertex has at least one color
        for v in range(n):
            cnf.append([var(v, c) for c in range(k)])

        # Adjacent vertices have different colors
        for u, v in edges:
            for c in range(k):
                cnf.append([-var(u, c), -var(v, c)])

        with Solver(name='g3', bootstrap_with=cnf) as solver:
            if solver.solve():
                return k
    return 7

