# Verify chromatic number
def get_chromatic_number(n, edges, max_k=6):
    for k in range(1, max_k+1):
        cnf = CNF()
        def var(v, c):
            return v * k + c + 1
        for v in range(n):
            cnf.append([var(v, c) for c in range(k)])
        for u, v in edges:
            for c in range(k):
                cnf.append([-var(u, c), -var(v, c)])
        with Solver(name='g3', bootstrap_with=cnf) as solver:
            if solver.solve():
                model = solver.get_model()
                coloring = {}
                for v in range(n):
                    for c in range(k):
                        if var(v,c) in model:
                            coloring[v] = c
                            break
                return k, coloring
    return max_k+1, None

chrom, coloring = get_chromatic_number(n, edges)
